function setProfileOpen(open,{returnFocus=false,focusClose=false}={}){
 const panel=$('inspector'),vp=$('viewport'),previousWidth=vp.clientWidth;
 state.profileOpen=Boolean(open);
 panel.hidden=!state.profileOpen;
 panel.classList.toggle('open',state.profileOpen);
 panel.setAttribute('aria-hidden',String(!state.profileOpen));
 document.querySelector('.layout').classList.toggle('profile-hidden',!state.profileOpen);
 if(state.profileOpen){
  $('sidebar').classList.remove('open');
  $('menuBtn').setAttribute('aria-expanded','false');
  $('searchResults').style.display='none';
 }
 updateProfileControls();
 // Keep the same part of the tree centered when the desktop sidebar closes.
 if(state.ready){state.panX+=(vp.clientWidth-previousWidth)/2;applyTransform();}
 if(state.profileOpen&&focusClose)$('closeProfileBtn').focus({preventScroll:true});
 else if(!state.profileOpen&&returnFocus)$('mobileInspectorBtn').focus({preventScroll:true});
}
function closeProfile(){setProfileOpen(false,{returnFocus:true});}
function setLang(language){state.lang=language;document.documentElement.lang=language;$('enBtn').classList.toggle('selected',language==='en');$('deBtn').classList.toggle('selected',language==='de');for(const el of document.querySelectorAll('[data-i18n]'))el.textContent=t(el.dataset.i18n);$('searchInput').placeholder=t('searchPlaceholder');$('directoryQuery').placeholder=t('directoryPlace');renderBranches();renderScene(false);renderProfile();updateProfileControls();if($('directoryDialog').open)renderDirectory();if($('reviewDialog').open)renderReview();try{localStorage.setItem('hor_lang',language);}catch(e){}}
function renderBranches(){let roots=DATA.metadata.curated_branches;$('branchList').innerHTML=roots.map((b,i)=>`<button class="branch ${b.id===state.root?'on':''}" data-branch="${esc(b.id)}"><span class="branch-dot">${String(i+1).padStart(2,'0')}</span><span><strong>${esc(state.lang==='de'?b.label_de:b.label_en)}</strong><small>${esc(life(I(b.id)))}</small></span></button>`).join('');}
function navigate(id,changeRoot=true,mode){if(!PEOPLE.has(id))return;state.selected=id;if(changeRoot){state.root=id;state.collapsed.clear();}if(mode)state.mode=mode;renderBranches();renderProfile();setProfileOpen(true,{focusClose:window.innerWidth<=1000});$('inspector').scrollTop=0;renderScene(true);$('searchInput').value='';}
const sortChildren=arr=>[...arr].sort((a,b)=>((I(a.id).birth||'9999').localeCompare(I(b.id).birth||'9999'))||S(a.id).localeCompare(S(b.id)));
function nodeTree(id,depth,seen,fam=null){let item={id,depth,children:[],edge:fam,more:false};if(seen.has(id))return item;let next=new Set(seen);next.add(id);let candidates=[];
 if(state.mode==='desc'){for(const f of unions.get(id)||[])for(const c of f.children)candidates.push({id:c,f});}
 else{const f=bornIn.get(id);if(f){for(const par of [f.primary,f.partner])if(par)candidates.push({id:par,f});}}
 item.more=candidates.length>0;
 if(depth<state.levels&&!state.collapsed.has(id))item.children=sortChildren(candidates).filter(c=>!next.has(c.id)).map(c=>nodeTree(c.id,depth+1,next,c.f));
 return item;}
const W=236,H=151,HG=38,VG=74,PAD=65;
function layoutTree(root){let max=0;function measure(n){max=Math.max(max,n.depth);if(!n.children.length){n.width=W;return n.width;}n.children.forEach(measure);n.width=Math.max(W,n.children.reduce((s,c)=>s+c.width,0)+(n.children.length-1)*HG);return n.width;}measure(root);let all=[];let edges=[];function pos(n,left){let cx;if(!n.children.length)cx=left+n.width/2;else{let cur=left;const centers=[];for(let c of n.children){pos(c,cur);centers.push(c.cx);cur+=c.width+HG;}cx=(centers[0]+centers[centers.length-1])/2;}n.cx=cx;n.y=state.mode==='desc'?n.depth*(H+VG):(max-n.depth)*(H+VG);all.push(n);for(const c of n.children){edges.push({from:n,to:c,f:c.edge});}}pos(root,PAD);let canvasW=root.width+PAD*2;let canvasH=(max+1)*(H+VG)+PAD*2;for(const n of all)n.y+=PAD;return {all,edges,canvasW,canvasH,max};}
function drawEdges(allEdges,w,h){let curves=allEdges.map(e=>{let a=e.from,b=e.to,down=state.mode==='desc';let ax=a.cx,ay=down?a.y+H:a.y;let bx=b.cx,by=down?b.y:b.y+H;let dy=by-ay;let c1=ay+dy*.5,c2=by-dy*.5;return `<path class="edge ${statusClass(e.f)}" d="M ${ax.toFixed(1)},${ay.toFixed(1)} C ${ax.toFixed(1)},${c1.toFixed(1)} ${bx.toFixed(1)},${c2.toFixed(1)} ${bx.toFixed(1)},${by.toFixed(1)}"/>`}).join('');return `<svg class="edges" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" aria-hidden="true">${curves}</svg>`;}
function drawCard(n){let p=I(n.id),partners=(unions.get(n.id)||[]).map(f=>f.primary===n.id?f.partner:f.primary).filter(Boolean).map(S);let spouse=partners.length?'∞ '+partners.join(' · '):'';let mark=n.edge&&statusClass(n.edge)!=='documented'?`<span class="node-flag ${statusClass(n.edge)==='needs_review'?'review':''}">${esc(statusClass(n.edge)==='probable'?t('probable'):t('review'))}</span>`:'';return `<button type="button" class="cardnode ${state.selected===n.id?'selected':''} ${n.edge?statusClass(n.edge):''}" data-node="${esc(n.id)}" style="left:${(n.cx-W/2).toFixed(1)}px;top:${n.y.toFixed(1)}px;" aria-label="${esc(p.name)}"><span class="nodehead"><span class="avatar">${esc(initials(p.name))}</span><span class="nodeinfo"><span class="person-name">${esc(p.name)}</span><span class="life">${esc(life(p))}</span></span></span><span class="node-spouse">${spouse?esc(spouse):'&nbsp;'}</span><span class="node-bottom">${mark||`<span>${esc(p.birth_place?places(p.birth_place):t('unknown'))}</span>`}${n.more?`<span class="node-expand" data-node-expand="${esc(n.id)}">${state.collapsed.has(n.id)||!n.children.length?'+':'−'}</span>`:''}</span></button>`;}
function renderScene(refit){if(!PEOPLE.has(state.root))return;let tree=nodeTree(state.root,0,new Set());let l=layoutTree(tree);state.nodes=l.all;state.coords=new Map(l.all.map(n=>[n.id,n]));state.worldW=l.canvasW;state.worldH=l.canvasH;$('scene').style.width=l.canvasW+'px';$('scene').style.height=l.canvasH+'px';$('scene').innerHTML=drawEdges(l.edges,l.canvasW,l.canvasH)+l.all.map(drawCard).join('');$('descBtn').classList.toggle('on',state.mode==='desc');$('ancBtn').classList.toggle('on',state.mode==='anc');let pr=I(state.root);$('canvasTitle').textContent=(state.mode==='desc'?t('descendants'):t('ancestors'))+' '+t('treeRoot')+' '+pr.name;$('canvasSubtitle').textContent=life(pr)+' · '+t('sourceNote');$('canvasMeta').textContent=l.all.length+' '+t('peopleShown')+' · '+DATA.people.length+' '+t('recordCount');if(refit||!state.ready){requestAnimationFrame(frameRoot);}}
function applyTransform(){$('scene').style.transform=`translate(${state.panX}px,${state.panY}px) scale(${state.zoom})`;}
function fit(){let vp=$('viewport');let aw=Math.max(1,vp.clientWidth-55),ah=Math.max(1,vp.clientHeight-55);state.zoom=Math.min(1.09,Math.max(.055,Math.min(aw/state.worldW,ah/state.worldH)));state.panX=(vp.clientWidth-state.worldW*state.zoom)/2;state.panY=(vp.clientHeight-state.worldH*state.zoom)/2;applyTransform();}
function frameRoot(){if(state.nodes.length<=9&&$('viewport').clientWidth>=700){fit();return;}let n=state.coords.get(state.root);if(!n)return fit();let vp=$('viewport');state.zoom=vp.clientWidth<570?.88:.92;state.panX=vp.clientWidth/2-n.cx*state.zoom;state.panY=(state.mode==='desc'?Math.max(82,vp.clientHeight*.17):vp.clientHeight*.64)-n.y*state.zoom;applyTransform();}
function zoomAt(factor,cx,cy){let s=Math.max(.055,Math.min(2.65,state.zoom*factor));let wx=(cx-state.panX)/state.zoom,wy=(cy-state.panY)/state.zoom;state.zoom=s;state.panX=cx-wx*s;state.panY=cy-wy*s;applyTransform();}
function centerSelected(){const n=state.coords.get(state.selected);if(!n)return fit();let vp=$('viewport');state.zoom=Math.min(1.05,Math.max(.64,state.zoom));state.panX=vp.clientWidth/2-n.cx*state.zoom;state.panY=vp.clientHeight/2-(n.y+H/2)*state.zoom;applyTransform();}
function profileSection(title,body){return `<section class="section"><h3>${esc(title)}</h3>${body}</section>`;}
function ancestorsPath(id){let path=[{id,status:'documented'}];let seen=new Set([id]);let current=id;for(let i=0;i<35;i++){let b=bornIn.get(current);if(!b)break;let par=b.primary;if(!par||seen.has(par))break;path.push({id:par,status:statusClass(b)});seen.add(par);current=par;if(current===ROOT_PERSON)break;}return path;}
function renderProfile(){let p=PEOPLE.get(state.selected);if(!p){$('profileDetails').textContent=t('notSelected');return;}let fam=bornIn.get(p.id),uf=unions.get(p.id)||[];let childIds=[...new Set(uf.flatMap(f=>f.children))];let html=`<div class="profile-eye">${esc(initials(p.name))}</div><h2 class="profile-name">${esc(p.name)}</h2><div class="profile-life">${esc(life(p))}</div><div class="profile-tags"><span class="tag">${esc((p.sources||[]).length)} ${esc(t('sources'))}</span><span class="tag">${esc(uf.length)} ${esc(t('families'))}</span>${fam&&statusClass(fam)!=='documented'?`<span class="tag ${statusClass(fam)}">${esc(statusClass(fam)==='probable'?t('probable'):t('review'))}</span>`:''}</div><div style="display:flex;gap:7px;flex-wrap:wrap"><button class="btn strong small" id="personDesc">↘ ${esc(t('descendants'))}</button><button class="btn small" id="personAnc">↖ ${esc(t('ancestors'))}</button></div>`;
 html+=profileSection(t('details'),`<div class="rowdata"><label>${esc(t('dateBirth'))}</label><b>${esc(p.birth?date(p.birth):t('unknown'))}${p.birth_place?' · '+esc(places(p.birth_place)):''}</b></div><div class="rowdata"><label>${esc(t('dateDeath'))}</label><b>${esc(p.death?date(p.death):t('unknown'))}${p.death_place?' · '+esc(places(p.death_place)):''}</b></div>`);
 html+=profileSection(t('parent'),fam?`<div class="familyitem"><div class="familytitle">${pButton(fam.primary)}${fam.partner?' · '+pButton(fam.partner):''}</div>${statusClass(fam)!=='documented'?`<span class="tag ${statusClass(fam)}">${esc(statusClass(fam)==='probable'?t('probable'):t('review'))}</span>`:''}</div>`:`<p class="footnote">${esc(t('parentsNotShown'))}</p>`);
 if(uf.length){let rows=uf.map(f=>{let other=f.primary===p.id?f.partner:f.primary;let ch=f.children||[];return `<div class="familyitem"><div class="familytitle">∞ ${other?pButton(other):esc(t('unknown'))}</div><small>${f.marriage?esc(t('married'))+': '+esc(date(f.marriage))+(f.marriage_place?' · '+esc(places(f.marriage_place)):''):'—'}</small><div class="childlist">${ch.map(id=>`<button data-person-link="${esc(id)}">${esc(S(id))}</button>`).join('')||`<small>${esc(t('noChildren'))}</small>`}</div>${statusClass(f)!=='documented'?`<div class="evidence ${statusClass(f)==='needs_review'?'review':''}">${esc((state.lang==='de'?f.notes_de:f.notes_en)||t('previewLabel'))}</div>`:''}</div>`}).join('');html+=profileSection(t('spouses')+' / '+t('children'),`<div class="familylist">${rows}</div>`);}
 let path=ancestorsPath(p.id);if(path.length>1){html+=profileSection(t('lineage'),`<div class="lineage">${path.map((step,i)=>`${i?'<span class="sep">‹</span>':''}${pButton(step.id)}${i&&step.status!=='documented'?'<span style="color:#be8c53">◇</span>':''}`).join('')}</div>${path.some(x=>x.status!=='documented')?`<p class="evidence">${esc(t('lineageCaution'))}</p>`:''}`);}
 else html+=profileSection(t('lineage'),`<div class="footnote">${esc(t('lineageNotFound'))}</div>`);
 if(p.notes)html+=profileSection(t('notes'),`<div class="footnote">${esc(p.notes)}</div>`);
 if(p.sources?.length)html+=profileSection(t('photoRefs'),`<div class="source-pills">${p.sources.map(s=>`<button data-photo="${esc(s)}">▧ ${esc(s.slice(4,8))}</button>`).join('')}</div><p class="footnote">${esc(t('photoTip'))}</p>`);
 $('profileDetails').innerHTML=html;
 $('personDesc').addEventListener('click',()=>navigate(state.selected,true,'desc'));
 $('personAnc').addEventListener('click',()=>navigate(state.selected,true,'anc'));
}
function showSearch(){let q=fold($('searchInput').value.trim());if(!q){$('searchResults').style.display='none';return;}let matches=DATA.people.filter(p=>fullSearch(p).includes(q)).sort((a,b)=>a.name.localeCompare(b.name,state.lang)).slice(0,22);$('searchResults').innerHTML=matches.map(p=>`<button class="result" data-person-link="${esc(p.id)}"><span><strong>${esc(p.name)}</strong><small>${esc(life(p))} · ${esc(places(p.birth_place))}</small></span><span>›</span></button>`).join('')||`<div class="lead" style="padding:12px">${esc(t('noMatch'))}</div>`;$('searchResults').style.display='block';}
function showDirectory(){renderDirectory();$('directoryDialog').showModal();}
function renderDirectory(){let q=fold($('directoryQuery').value);let names=DATA.people.filter(p=>!q||fullSearch(p).includes(q)).sort((a,b)=>a.name.localeCompare(b.name,state.lang));$('directoryStatus').textContent=names.length+' '+t('recordCount');$('directoryBody').innerHTML=names.map(p=>`<tr><td><button data-person-link="${esc(p.id)}">${esc(p.name)}</button></td><td>${esc(p.birth?date(p.birth):'—')}</td><td>${esc(p.death?date(p.death):'—')}</td><td>${esc((p.sources||[]).slice(0,3).map(s=>s.slice(4,8)).join(' · '))}</td></tr>`).join('');}
function showPhoto(filename){state.photoIndex=Math.max(0,photoNames.indexOf(filename));state.zoomPhoto=false;updatePhoto();if(!$('photoDialog').open)$('photoDialog').showModal();}
function updatePhoto(){let fn=photoNames[state.photoIndex];$('photoImage').src='data:image/jpeg;base64,'+PHOTO_DATA[fn];$('photoSelect').value=fn;$('photoImage').classList.toggle('enlarged',state.zoomPhoto);$('prevPhoto').disabled=state.photoIndex===0;$('nextPhoto').disabled=state.photoIndex===photoNames.length-1;$('photoViewer').scrollTop=0;$('photoViewer').scrollLeft=0;}
function renderReview(){let statuses=['documented','probable','needs_review'];$('auditTotals').innerHTML=statuses.map(st=>`<div><strong>${DATA.families.filter(f=>statusClass(f)===st).length}</strong><span>${esc(st==='documented'?t('documented'):st==='probable'?t('probable'):t('review'))}</span></div>`).join('');let aud=DATA.families.filter(f=>statusClass(f)!=='documented');$('reviewBody').innerHTML=aud.map(f=>`<div class="review-modal-item"><span class="tag ${statusClass(f)}">${esc(statusClass(f)==='probable'?t('probable'):t('review'))}</span><div style="margin-top:7px"><strong>${esc(S(f.primary))}</strong> ∞ <strong>${esc(f.partner?S(f.partner):t('unknown'))}</strong></div><p>${esc((state.lang==='de'?f.notes_de:f.notes_en)||t('previewLabel'))}</p><p>${esc(f.children.length)} ${esc(t('childCount'))} · ${esc((f.sources||[]).map(s=>s.slice(4,8)).join(' · '))}</p><button class="btn small" data-person-link="${esc(f.primary)}">${esc(t('view'))} ↗</button>${f.sources?.length?` <button class="btn small" data-photo="${esc(f.sources[0])}">▧ ${esc(t('sources'))}</button>`:''}</div>`).join('');}
function downloadData(){let blob=new Blob([JSON.stringify(DATA,null,2)],{type:'application/json;charset=utf-8'});let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Family_Archive_Data_v5_PRIVATE.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function init(){try{let s=localStorage.getItem('hor_lang');if(s==='de')state.lang='de';}catch(e){}
 $('peopleCount').textContent=DATA.people.length;$('familyCount').textContent=DATA.families.length;$('photoCount').textContent=photoNames.length;$('linkedCount').textContent=Math.max(...DATA.metadata.component_sizes);
 $('photoSelect').innerHTML=photoNames.map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('');
 $('menuBtn').addEventListener('click',()=>{const open=!$('sidebar').classList.contains('open');if(open&&window.innerWidth<=1000)setProfileOpen(false);$('sidebar').classList.toggle('open',open);$('menuBtn').setAttribute('aria-expanded',String(open));});
 $('mobileInspectorBtn').addEventListener('click',()=>setProfileOpen(!state.profileOpen,{focusClose:true}));
 $('closeProfileBtn').addEventListener('click',closeProfile);
 $('enBtn').addEventListener('click',()=>setLang('en'));$('deBtn').addEventListener('click',()=>setLang('de'));
 $('descBtn').addEventListener('click',()=>{state.mode='desc';state.collapsed.clear();renderScene(true);});$('ancBtn').addEventListener('click',()=>{state.mode='anc';state.collapsed.clear();renderScene(true);});
 $('depthSelect').addEventListener('change',e=>{state.levels=+e.target.value;state.collapsed.clear();renderScene(true);});
 $('centerBtn').addEventListener('click',frameRoot);$('fitBtn').addEventListener('click',fit);$('zoomInBtn').addEventListener('click',()=>zoomAt(1.33,$('viewport').clientWidth/2,$('viewport').clientHeight/2));$('zoomOutBtn').addEventListener('click',()=>zoomAt(1/1.33,$('viewport').clientWidth/2,$('viewport').clientHeight/2));
 $('oldestBtn').addEventListener('click',()=>navigate(ROOT_PERSON,true,'desc'));
 $('homeBranchBtn').addEventListener('click',()=>navigate(HOME_PERSON,true,'anc'));
 $('directoryBtn').addEventListener('click',showDirectory);$('photoBtn').addEventListener('click',()=>showPhoto(photoNames[0]));$('reviewBtn').addEventListener('click',()=>{renderReview();$('reviewDialog').showModal();});$('exportBtn').addEventListener('click',downloadData);
 $('directoryQuery').addEventListener('input',renderDirectory);
 $('searchInput').addEventListener('input',showSearch);$('searchInput').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();let q=fold($('searchInput').value.trim());if(!q)return;let a=DATA.people.find(p=>fullSearch(p).includes(q));if(a)navigate(a.id,true,'anc');}if(e.key==='Escape')$('searchResults').style.display='none';});
 $('branchList').addEventListener('click',e=>{let btn=e.target.closest('[data-branch]');if(btn)navigate(btn.dataset.branch,true,'desc');});
 $('scene').addEventListener('click',e=>{let ex=e.target.closest('[data-node-expand]');if(ex){e.preventDefault();e.stopPropagation();let id=ex.dataset.nodeExpand;let n=state.nodes.find(x=>x.id===id);if(n&&n.depth>=state.levels&&!state.collapsed.has(id)){state.levels=Math.min(11,n.depth+1);$('depthSelect').value=String(state.levels);}else if(state.collapsed.has(id))state.collapsed.delete(id);else state.collapsed.add(id);renderScene(false);return;}let node=e.target.closest('[data-node]');if(node){state.selected=node.dataset.node;renderProfile();setProfileOpen(true,{focusClose:window.innerWidth<=1000});$('inspector').scrollTop=0;renderScene(false);}});
 document.addEventListener('click',e=>{if(!$('appRoot')?.firstElementChild)return;let p=e.target.closest('[data-person-link]');if(p){const dia=p.closest('dialog');if(dia)dia.close();navigate(p.dataset.personLink,true,'anc');return;}let photo=e.target.closest('[data-photo]');if(photo){showPhoto(photo.dataset.photo);return;}let close=e.target.closest('[data-close]');if(close){$(close.dataset.close).close();return;}if(!e.target.closest('.search-box')&&!e.target.closest('#searchResults'))$('searchResults').style.display='none';});
 $('prevPhoto').addEventListener('click',()=>{state.photoIndex=Math.max(0,state.photoIndex-1);state.zoomPhoto=false;updatePhoto();});$('nextPhoto').addEventListener('click',()=>{state.photoIndex=Math.min(photoNames.length-1,state.photoIndex+1);state.zoomPhoto=false;updatePhoto();});$('photoSelect').addEventListener('change',e=>{state.photoIndex=photoNames.indexOf(e.target.value);state.zoomPhoto=false;updatePhoto();});$('photoZoomBtn').addEventListener('click',()=>{state.zoomPhoto=!state.zoomPhoto;$('photoImage').classList.toggle('enlarged',state.zoomPhoto);});$('photoImage').addEventListener('click',()=>$('photoZoomBtn').click());
 let vp=$('viewport');vp.addEventListener('wheel',e=>{e.preventDefault();let r=vp.getBoundingClientRect();zoomAt(Math.exp(-e.deltaY*.0016),e.clientX-r.left,e.clientY-r.top);},{passive:false});
 vp.addEventListener('pointerdown',e=>{if(e.target.closest('[data-node]'))return;vp.setPointerCapture(e.pointerId);state.pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});state.drag={x:e.clientX,y:e.clientY};vp.classList.add('dragging');});
 vp.addEventListener('pointermove',e=>{let prev=state.pointers.get(e.pointerId);if(!prev)return;state.pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(state.pointers.size===1&&state.drag){state.panX+=e.clientX-state.drag.x;state.panY+=e.clientY-state.drag.y;state.drag={x:e.clientX,y:e.clientY};applyTransform();}else if(state.pointers.size===2){let other=[...state.pointers.entries()].find(([id])=>id!==e.pointerId)?.[1];if(other){let d0=Math.hypot(prev.x-other.x,prev.y-other.y),d1=Math.hypot(e.clientX-other.x,e.clientY-other.y),r=vp.getBoundingClientRect();if(d0>3&&d1>3)zoomAt(d1/d0,(e.clientX+other.x)/2-r.left,(e.clientY+other.y)/2-r.top);}}});
 let end=e=>{state.pointers.delete(e.pointerId);state.drag=null;if(!state.pointers.size)vp.classList.remove('dragging');};vp.addEventListener('pointerup',end);vp.addEventListener('pointercancel',end);vp.addEventListener('lostpointercapture',end);
 window.addEventListener('resize',()=>{if(state.ready)frameRoot();});
 document.addEventListener('keydown',e=>{
  if(e.key==='Escape'&&!document.querySelector('dialog[open]')){
   if(state.profileOpen){e.preventDefault();closeProfile();return;}
   if($('sidebar').classList.contains('open')){e.preventDefault();$('sidebar').classList.remove('open');$('menuBtn').setAttribute('aria-expanded','false');$('menuBtn').focus();}
  }
  if($('photoDialog').open){if(e.key==='ArrowLeft'&&state.photoIndex>0){state.photoIndex--;updatePhoto();}else if(e.key==='ArrowRight'&&state.photoIndex<photoNames.length-1){state.photoIndex++;updatePhoto();}}});
 setProfileOpen(state.profileOpen);setLang(state.lang);state.ready=true;renderScene(true);renderProfile();}
