function hydrateIcons(){document.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML='<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">'+(ICONS[el.dataset.icon]||'')+'</svg>';});}
const originalRenderProfile=renderProfile;
renderProfile=function(){originalRenderProfile();const p=PEOPLE.get(state.selected);if(!p)return;const a=p.name_review;if(!a)return;const review=a.status==='needs_review';const changed=a.status==='corrected';const el=document.createElement('div');el.className='name-proof'+(review?' review':'');el.innerHTML='<strong>'+esc(t(review?'nameUnclear':'printedName'))+'</strong><span class="printed">'+esc(p.name)+'</span>'+(changed?'<span class="old">'+esc(a.previous)+'</span>':'')+'<div>'+esc(state.lang==='de'?a.note_de:a.note_en)+'</div>'+(a.source?'<button data-photo="'+esc(a.source)+'">'+esc(t('viewPhoto'))+' \u00b7 '+esc(a.source.slice(4,8))+'</button>':'');const first=$('profileDetails').querySelector('.section');$('profileDetails').insertBefore(el,first);};
const originalApplyTransform=applyTransform;
applyTransform=function(){originalApplyTransform();if($('zoomLabel'))$('zoomLabel').textContent=Math.round(state.zoom*100)+'%';updateMapViewport();};
function drawMinimap(){const s=$('miniSvg');if(!s)return;s.setAttribute('viewBox','0 0 '+state.worldW+' '+state.worldH);s.innerHTML=state.nodes.map(n=>'<rect class="mapnode '+(n.id===state.selected?'active':'')+'" x="'+(n.cx-W/2)+'" y="'+n.y+'" width="'+W+'" height="'+H+'" rx="10"/>').join('')+'<rect class="maprect" id="mapWindow"/>';updateMapViewport();}
function updateMapViewport(){const r=$('mapWindow');if(!r)return;const vp=$('viewport');r.setAttribute('x',-state.panX/state.zoom);r.setAttribute('y',-state.panY/state.zoom);r.setAttribute('width',vp.clientWidth/state.zoom);r.setAttribute('height',vp.clientHeight/state.zoom);}
const originalRenderScene=renderScene;
renderScene=function(refit){originalRenderScene(refit);drawMinimap();$('backBtn').disabled=viewHistory.length===0;};
const viewHistory=[];let restoringHistory=false;
const originalNavigate=navigate;
navigate=function(id,changeRoot=true,mode){if(!PEOPLE.has(id))return;if(changeRoot&&!restoringHistory&&(id!==state.root||(mode&&mode!==state.mode)))viewHistory.push({root:state.root,selected:state.selected,mode:state.mode,levels:state.levels});originalNavigate(id,changeRoot,mode);refreshBackdrop();};
const originalProfileOpen=setProfileOpen;
setProfileOpen=function(open,opts={}){originalProfileOpen(open,opts);refreshBackdrop();};
function refreshBackdrop(){const open=$('sidebar').classList.contains('open')||(state.profileOpen&&window.innerWidth<=1000);$('drawerBackdrop').hidden=!open;}
const originalSetLang=setLang;
setLang=function(lang){originalSetLang(lang);document.title=t('brandTitle');$('brandSurnames').textContent=DATA.metadata.subtitle;document.querySelectorAll('[data-title]').forEach(el=>{el.title=t(el.dataset.title);el.setAttribute('aria-label',t(el.dataset.title));});$('menuBtn').setAttribute('aria-label',lang==='de'?'Navigation \u00f6ffnen':'Open navigation');$('nameQuery').placeholder=t('directoryPlace');$('nameQuery').setAttribute('aria-label',t('nameAudit'));$('depthSelect').setAttribute('aria-label',t('levels'));$('minimap').setAttribute('aria-label',t('overviewLabel'));$('privacyDetail').textContent=t(options.encrypted?'privacyEncrypted':'privacyOffline');$('nameCorrectionCount').textContent=DATA.metadata.name_changes;$('announcements').textContent=lang==='de'?'Sprache: Deutsch':'Language: English';if($('nameDialog').open)renderNameAudit();hydrateIcons();};
const originalUpdatePhoto=updatePhoto;
updatePhoto=function(){originalUpdatePhoto();$('photoImage').alt=t('originals')+' '+photoNames[state.photoIndex];};
let nameFilter='corrected';
function showNames(){renderNameAudit();$('nameDialog').showModal();}
function renderNameAudit(){let q=fold($('nameQuery').value);const ps=DATA.people.filter(p=>(nameFilter==='all'||p.name_review.status===nameFilter)&&(!q||fullSearch(p).includes(q))).sort((a,b)=>a.name.localeCompare(b.name,state.lang));document.querySelectorAll('[data-name-filter]').forEach(b=>b.classList.toggle('active',b.dataset.nameFilter===nameFilter));$('nameAuditStats').textContent=ps.length+' '+t('nameRecords');$('nameEntries').innerHTML=ps.map(p=>{const a=p.name_review;return '<article class="name-entry"><small>'+esc(a.source||'')+' \u00b7 '+esc(t(a.status==='needs_review'?'nameUnclear':'nameChecked'))+'</small>'+(a.status==='corrected'?'<div class="old">'+esc(a.previous)+'</div>':'')+'<h3>'+esc(p.name)+'</h3><p>'+esc(state.lang==='de'?a.note_de:a.note_en)+'</p><div class="actions"><button class="btn small" data-person-link="'+esc(p.id)+'">'+esc(t('profileToggleText'))+'</button><button class="btn small" data-photo="'+esc(a.source)+'">'+esc(t('viewPhoto'))+'</button></div></article>';}).join('')||'<p class="empty-note">'+esc(t('noMatch'))+'</p>';$('nameFindings').innerHTML='<strong>'+esc(t('nameFindings'))+'</strong>'+DATA.metadata.name_audit_findings.map(f=>'<p>'+esc(state.lang==='de'?f.de:f.en)+' <button class="btn small" data-photo="'+esc(f.source)+'">'+esc(f.source)+'</button></p>').join('');}
function downloadCsv(){const rows=[['record_id','previous_name','displayed_name','status','photo','note_English','note_German'],...DATA.people.map(p=>[p.id,p.name_review.previous,p.name,p.name_review.status,p.name_review.source,p.name_review.note_en,p.name_review.note_de])];const csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v||'').replaceAll('"','""')+'"').join(',')).join('\r\n');downloadBlob(new Blob([csv],{type:'text/csv;charset=utf-8'}),'Family_Archive_Name_Audit.csv');}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
let toastTimer;
function toast(msg){$('toast').textContent=msg;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,3500);}
function extraInit(){
 $('nameAuditBtn').addEventListener('click',showNames);$('nameQuery').addEventListener('input',renderNameAudit);$('nameCsvBtn').addEventListener('click',downloadCsv);
 document.querySelectorAll('[data-name-filter]').forEach(b=>b.addEventListener('click',()=>{nameFilter=b.dataset.nameFilter;renderNameAudit();}));
 $('helpBtn').addEventListener('click',()=>$('helpDialog').showModal());
 $('lockBtn').hidden=!options.encrypted;$('lockBtn').addEventListener('click',e=>{e.stopPropagation();window.lockFamilyArchive();});
 $('backBtn').addEventListener('click',()=>{const old=viewHistory.pop();if(!old)return;restoringHistory=true;state.levels=old.levels;$('depthSelect').value=String(old.levels);navigate(old.root,true,old.mode);state.selected=old.selected;renderProfile();restoringHistory=false;$('backBtn').disabled=!viewHistory.length;});
 $('fullScreenBtn').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast(t('unsupported'));}catch(e){toast(t('unsupported'));}});
 $('minimap').addEventListener('click',e=>{const svg=$('miniSvg');let p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;p=p.matrixTransform(svg.getScreenCTM().inverse());state.panX=$('viewport').clientWidth/2-p.x*state.zoom;state.panY=$('viewport').clientHeight/2-p.y*state.zoom;applyTransform();});
 $('minimap').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();fit();}});
 $('drawerBackdrop').addEventListener('click',()=>{$('sidebar').classList.remove('open');$('menuBtn').setAttribute('aria-expanded','false');setProfileOpen(false);refreshBackdrop();});
 $('menuBtn').addEventListener('click',refreshBackdrop);
 window.addEventListener('resize',refreshBackdrop);
 document.addEventListener('keydown',e=>{if(e.key==='/'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!e.target.closest('input,textarea,select')&&!document.querySelector('dialog[open]')){e.preventDefault();$('searchInput').focus();}if(e.key==='Escape')setTimeout(refreshBackdrop,0);});
 $('searchInput').addEventListener('keydown',e=>{if(e.key==='ArrowDown'){const first=$('searchResults').querySelector('button');if(first){e.preventDefault();first.focus();}}});
 $('searchResults').addEventListener('keydown',e=>{const rows=[...$('searchResults').querySelectorAll('button')];const i=rows.indexOf(document.activeElement);if(e.key==='ArrowDown'&&i<rows.length-1){e.preventDefault();rows[i+1].focus();}if(e.key==='ArrowUp'){e.preventDefault();if(i>0)rows[i-1].focus();else $('searchInput').focus();}});
 document.querySelectorAll('[data-mobile-action]').forEach(b=>b.addEventListener('click',()=>{const a=b.dataset.mobileAction;$('sidebar').classList.remove('open');$('menuBtn').setAttribute('aria-expanded','false');refreshBackdrop();if(a==='directory')showDirectory();if(a==='photos')showPhoto(photoNames[0]);if(a==='review'){renderReview();$('reviewDialog').showModal();}if(a==='help')$('helpDialog').showModal();if(a==='profile')setProfileOpen(true,{focusClose:true});if(a==='export')downloadData();}));
 document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
 setLang(state.lang);refreshBackdrop();
}
