function openCrest(){window.applyArchiveBranding?.();$('crestStatus').textContent='';$('crestDialog').showModal();}
function crestInit(){
 $('crestBtn').addEventListener('click',openCrest);
 $('welcomeBtn').addEventListener('click',e=>{e.stopPropagation();window.showArchiveWelcome?.();});
 document.querySelector('[data-mobile-action="crest"]').addEventListener('click',()=>{$('sidebar').classList.remove('open');refreshBackdrop();openCrest();});
 $('crestFile').addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;try{await window.importArchiveCrest(f);$('crestStatus').textContent=t('crestSaved');}catch(err){$('crestStatus').textContent=t('crestError');}e.target.value='';});
 $('saveBrandBtn').addEventListener('click',()=>{downloadBlob(new Blob([JSON.stringify(window.familyArchiveBranding||{},null,2)],{type:'application/json'}),'branding.json');});
 $('saveOfflineBrandBtn').hidden=!!options.encrypted;
 $('saveOfflineBrandBtn').addEventListener('click',()=>{if(confirm(t('privateExport')))window.saveBrandedOffline?.();});
 $('removeCrestBtn').addEventListener('click',()=>{window.setArchiveBranding?.({});$('crestStatus').textContent=t('crestRemoved');});
 window.applyArchiveBranding?.();
 const oldLang=setLang;
 setLang=function(lang){oldLang(lang);window.setShellLanguage?.(lang);window.applyArchiveBranding?.();};
 setLang(state.lang);
}

try{init();extraInit();crestInit();window.familyArchiveReady=true;}catch(err){console.error(err);document.getElementById('appRoot').innerHTML='<div class=empty-note>Unable to start the archive. Please open the HTML in a full browser. / Bitte in einem vollständigen Browser öffnen.<br>'+esc(String(err))+'</div>';throw err;}
